import Foundation

@main
enum MoonPhaseChecks {
    static func main() {
        let formatter = ISO8601DateFormatter()
        func date(_ value: String) -> Date { formatter.date(from: value)! }
        func distance(_ a: Double, _ b: Double) -> Double {
            let delta = abs(a - b)
            return min(delta, 1 - delta)
        }

        // Independent published UT event instants, not generated by MoonPhase.
        // NASA/GSFC, Fred Espenak: https://eclipse.gsfc.nasa.gov/phase/phases1901.html
        // https://eclipse.gsfc.nasa.gov/phase/phases2001.html
        // USNO: https://aa.usno.navy.mil/api/moon/phases/year?year=2026
        let events: [(String, Double, String)] = [
            ("1901-01-05T00:13:00Z", 0.5, "满月"),
            ("1901-01-20T14:36:00Z", 0, "新月"),
            ("2000-01-06T18:14:00Z", 0, "新月"),
            ("2000-01-14T13:34:00Z", 0.25, "上弦月"),
            ("2000-01-21T04:40:00Z", 0.5, "满月"),
            ("2000-01-28T07:57:00Z", 0.75, "下弦月"),
            ("2026-01-03T10:03:00Z", 0.5, "满月"),
            ("2026-01-18T19:52:00Z", 0, "新月"),
            ("2026-07-14T09:43:00Z", 0, "新月"),
            ("2026-07-29T14:36:00Z", 0.5, "满月"),
            ("2026-11-09T07:02:00Z", 0, "新月"),
            ("2026-11-17T11:48:00Z", 0.25, "上弦月"),
            ("2026-11-24T14:53:00Z", 0.5, "满月"),
            ("2026-12-01T06:08:00Z", 0.75, "下弦月"),
            ("2026-12-09T00:52:00Z", 0, "新月"),
            ("2026-12-24T01:28:00Z", 0.5, "满月"),
            ("2100-01-10T12:55:00Z", 0, "新月"),
            ("2100-01-18T12:34:00Z", 0.25, "上弦月"),
            ("2100-01-26T02:49:00Z", 0.5, "满月"),
            ("2100-02-01T21:16:00Z", 0.75, "下弦月")
        ]
        var largestError = 0.0
        for (timestamp, expected, label) in events {
            let instant = date(timestamp)
            let phase = MoonPhase(at: instant)
            let error = distance(phase.fraction, expected)
            largestError = max(largestError, error)
            // 1% of a lunation (~7 hours) is a visual acceptance bound,
            // not a promise of exact phase-event timing for every date.
            precondition(error < 0.01, "Phase disagreement at \(timestamp): \(phase.fraction)")
            precondition(phase.label == label)
            if expected == 0 { precondition(phase.illumination < 0.001) }
            if expected == 0.5 { precondition(phase.illumination > 0.999) }
            if expected == 0.25 || expected == 0.75 {
                precondition(abs(phase.illumination - 0.5) < 0.03)
                precondition(phase.isWaxing == (expected == 0.25))
            }
            // Do not demand exact-minute agreement from a low-order formula.
            // One day either side must correctly distinguish waxing/waning.
            if expected == 0 || expected == 0.5 {
                let before = MoonPhase(at: instant - 86_400)
                let after = MoonPhase(at: instant + 86_400)
                precondition(before.isWaxing == (expected == 0.5))
                precondition(after.isWaxing == (expected == 0))
            }
        }

        // Same instant represented across the local-date boundary yields the
        // same phase. This catches Calendar/current-time-zone implementations.
        let universal = MoonPhase(at: date("2026-11-09T00:30:00Z"))
        precondition(universal == MoonPhase(at: date("2026-11-09T08:30:00+08:00")))
        precondition(universal == MoonPhase(at: date("2026-11-08T16:30:00-08:00")))

        // Hourly sampling crosses every phase and the new-moon wrap. No NaNs,
        // out-of-range values, backward phase motion or discontinuous disk size.
        let start = date("2026-10-20T00:00:00Z")
        var previous = MoonPhase(at: start)
        var labels = Set([previous.label])
        for hour in 1...(75 * 24) {
            let current = MoonPhase(at: start + Double(hour) * 3600)
            precondition((0..<1).contains(current.fraction) && current.fraction.isFinite)
            precondition((0...1).contains(current.illumination) && current.illumination.isFinite)
            var advance = current.fraction - previous.fraction
            if advance < 0 { advance += 1 }
            precondition(advance > 0 && advance < 0.003, "Phase must advance smoothly")
            precondition(abs(current.illumination - previous.illumination) < 0.01)
            labels.insert(current.label)
            previous = current
        }
        precondition(labels.count == 8)
        print("MoonPhase checks passed: \(events.count) published events; max cycle error \(largestError); UTC invariance and 75-day hourly continuity.")
    }
}
